import sys
from collections import deque

def captainAmerica(n, m, v):
    adj = [[] for _ in range(n + 1)]
    rev_adj = [[] for _ in range(n + 1)]

    for u, w in v:
        adj[u].append(w)
        rev_adj[w].append(u)

    # Step 1: Find a node in the sink SCC using Kosaraju's first pass (DFS on original graph)
    visited = [False] * (n + 1)
    order = []

    def dfs1(node):
        stack = [(node, False)]
        while stack:
            u, processed = stack.pop()
            if processed:
                continue
            if visited[u]:
                continue
            visited[u] = True
            stack.append((u, True))
            for neighbor in adj[u]:
                if not visited[neighbor]:
                    stack.append((neighbor, False))

    for i in range(1, n + 1):
        if not visited[i]:
            dfs1(i)

    # The last finished node in DFS is a candidate for sink SCC
    candidate = order[-1] if order else None

    # Step 2: DFS on reversed graph from candidate to find all nodes in its SCC
    visited2 = [False] * (n + 1)
    count = 0

    def dfs2(node):
        nonlocal count
        stack = [node]
        while stack:
            u = stack.pop()
            if visited2[u]:
                continue
            visited2[u] = True
            count += 1
            for neighbor in rev_adj[u]:
                if not visited2[neighbor]:
                    stack.append(neighbor)

    if candidate is not None:
        dfs2(candidate)

    return count

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    iterator = iter(data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    v = []
    for _ in range(m):
        try:
            u = int(next(iterator))
            w = int(next(iterator))
            v.append([u, w])
        except StopIteration:
            break

    result = captainAmerica(n, m, v)
    print(result)

if __name__ == "__main__":
    main()
